package kz.zani.mobile

import kotlinx.coroutines.*
import kotlinx.coroutines.test.*
import kz.zani.mobile.core.*
import kz.zani.mobile.data.*
import kz.zani.mobile.ui.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

@OptIn(ExperimentalCoroutinesApi::class)
class AppointmentBookingDirectoryTest {
    private fun fixture(name:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$name.json")!!.bufferedReader().use {it.readText()}
    private fun source():AppointmentBookingSource {val s=AgendaSession();s.install(JsonContracts.bootstrap(fixture("bootstrap")));val page=JsonContracts.appointments(fixture("appointments-101"));val scope=s.begin(101,page.date);s.receive(page,scope);return AppointmentBookingSource(s.beginDetail(501),1,7001,8001,9001)}
    private fun transport()=ReadTransport {q->val id=q.path.trimEnd('/').substringAfterLast('/');val name=when {q.path.endsWith("/bootstrap/")->"bootstrap";q.path.startsWith("/api/services/")->"service-reference-$id";q.path.startsWith("/api/resources/")->"resource-reference-$id";q.path.startsWith("/api/mobile/v1/clients/")->"client-${q.query["business"]}-$id";q.path.endsWith("/appointments/")->"appointments-${q.query["business"]}";else->"appointment-${q.query["business"]}-$id"};ReadResponse(200,fixture(name))}
    private fun directoryPort(name:String)=ReadTransport {q->val rows=JSONObject(fixture(name)).getJSONArray("reads");val row=(0 until rows.length()).map {rows.getJSONObject(it)}.first {it.getString("path")==q.path && q.query.isEmpty()};ReadResponse(200,row.getString("response_json"))}
    private fun services()=APIServiceDirectoryRepository(directoryPort("service-directory"))
    private fun resources()=APIResourceDirectoryRepository(directoryPort("resource-directory"))
    private fun port()=FixtureAppointmentBookingPort.fromJSON(fixture("appointment-booking"))
    private class Held:ServiceDirectoryRepository {
        val windows=mutableListOf<CompletableDeferred<ServiceDirectoryWindow>>()
        override suspend fun services(business:Int):ServiceDirectoryWindow=CompletableDeferred<ServiceDirectoryWindow>().also {windows.add(it)}.await()
        override suspend fun service(business:Int,id:Int):ServiceDirectoryItem=error("No automatic detail expected")
    }
    private class ActorPort(override var grants:List<SyntheticAppointmentBookingGrant>):SyntheticAppointmentBookingPort {override suspend fun execute(attempt:AppointmentBookingAttempt):SyntheticAppointmentBookingOutcome=SyntheticAppointmentBookingOutcome.Unknown}
    @Test fun sharedFieldProofLegacyScopeClientAndFiveFieldBody()=runTest {
        val base=source();val repo=APIReadRepository(transport());val clients=mapOf(7001 to TaskDraftClientChoice.make(repo.clientProfile(101,7001),101,7001)!!,7002 to TaskDraftClientChoice.make(repo.clientProfile(101,7002),101,7002)!!);val sr=services();val rr=resources();val sm=mapOf(8001 to sr.service(101,8001),8003 to sr.service(101,8003),8002 to sr.service(202,8002));val rm=mapOf(9001 to rr.resource(101,9001),9003 to rr.resource(101,9003),9002 to rr.resource(202,9002));val cases=JSONObject(fixture("appointment-booking-directory")).getJSONArray("cases")
        for(i in 0 until cases.length()) {val row=cases.getJSONObject(i);val s=base.copy(epoch=row.getInt("source_epoch"));val cs=base.copy(epoch=row.getInt("choice_epoch"));val wanted=row.getBoolean("proof");val ps=if(row.isNull("proof_service"))null else sm[row.getInt("proof_service")];val pr=if(row.isNull("proof_resource"))null else rm[row.getInt("proof_resource")];val proof=if(wanted)AppointmentBookingDirectorySelection.make(cs,ps,pr)else null;var service=sm[row.getInt("service")]!!.reference;if(row.getBoolean("mutate_name"))service=service.copy(name=service.name+"changed");val resource=if(row.isNull("resource"))AppointmentRescheduleResource.Clear else AppointmentRescheduleResource.Linked(rm[row.getInt("resource")]!!.reference);val input=if(wanted && proof==null)null else AppointmentBookingInput.prepare(s,clients[row.getInt("client")]!!,service,resource,"2026-10-29T05:00:00Z",proof);assertEquals(row.getString("name"),row.getBoolean("valid"),input!=null);if(input!=null){assertTrue(input.valid(s));val body=JSONObject(input.body(101)!!);assertEquals(setOf("business","client","service","start_at","resource"),body.keys().asSequence().toSet());assertEquals(service.id,body.getInt("service"));assertEquals(resource.id,if(body.isNull("resource"))null else body.getInt("resource"))}}
        val proof=AppointmentBookingDirectorySelection.make(base,sm[8003],rm[9003])!!;val input=AppointmentBookingInput.prepare(base,clients[7001]!!,sm[8003]!!.reference,AppointmentRescheduleResource.Linked(rm[9003]!!.reference),"2026-10-29T05:00:00Z",proof)!!;assertFalse(sm[8003]!!.isActive);assertFalse(rm[9003]!!.hasKnownType);assertNull(SyntheticAppointmentBookingGrant(101,501,5001,false).authorization(base));val auth=SyntheticAppointmentBookingGrant(101,501,5001,true).authorization(base)!!;val ledger=AppointmentBookingLedger();val review=AppointmentBookingReview(base,input,1);val a=ledger.begin(review,auth)!!;val reply=JSONObject(JSONObject(fixture("appointment-booking")).getJSONArray("scenarios").getJSONObject(0).getString("response_json")).put("service",8003).put("resource",9003);ledger.complete(a,SyntheticAppointmentBookingOutcome.Response(201,reply.toString()));assertEquals(AppointmentBookingPhase.ACCEPTED_FIXTURE,ledger.records[0].phase);assertEquals(proof,ledger.records[0].attempt.review.input.directory)
        val unknown=AppointmentBookingLedger();val retained=unknown.begin(review,auth)!!;unknown.complete(retained,SyntheticAppointmentBookingOutcome.Unknown);assertEquals(sm[8003],sr.service(101,8003));assertEquals(rm[9003],rr.resource(101,9003));assertTrue(unknown.blocked(base));assertNull(unknown.begin(review,auth));assertFalse(unknown.acknowledge(unknown.records[0]));assertEquals(retained,unknown.records[0].attempt)
    }
    @Test fun actualFormOwnedUseSnapshotsExplicitClearAndUnknownQuarantine()=runTest {
        val repo=APIReadRepository(transport());val s=source();val b=AppointmentBookingModel(port(),repo,APIAppointmentReferenceRepository(transport()),services(),resources());b.bind(s);b.open(b.control);b.setStart("2026-10-29T05:00:00Z",b.inputControl);b.load(AppointmentBookingReadKind.CLIENT,b.control);val client=b.client;val raw=b.rawStart;val oldInput=b.inputControl;val oldAction=b.control;val service=b.serviceChoices!!;val resource=b.resourceChoices!!
        b.openSelector(AppointmentBookingDirectoryKind.SERVICE,b.control,service.control,resource.control);val session=b.selectorControl!!;assertFalse(b.editing);assertNull(b.inputControl);b.setStart("stale",oldInput);b.chooseClear(oldAction);assertEquals(raw,b.rawStart);assertNull(b.resource)
        service.select(service.window!!.items.first {it.id==8003},service.control);service.choose(service.control);val choice=service.choice!!;val leaf=service.control;assertNull(b.service);b.useService(choice,leaf,session);assertEquals(8003,b.service!!.id);assertEquals(choice.item,b.directory!!.service);assertNull(b.resource);assertFalse(b.canReview);assertEquals(client,b.client);assertEquals(raw,b.rawStart);assertNull(service.owner)
        b.openSelector(AppointmentBookingDirectoryKind.RESOURCE,b.control,service.control,resource.control);val resourceSession=b.selectorControl!!;resource.select(resource.window!!.items.first {it.id==9003},resource.control);resource.choose(resource.control);val chosen=resource.choice!!;val rleaf=resource.control;b.useResource(chosen,rleaf,resourceSession);assertEquals(9003,b.resource!!.id);assertEquals(choice.item,b.directory!!.service);assertEquals(chosen.item,b.directory!!.resource);assertTrue(b.canReview);b.chooseClear(b.control);assertEquals(AppointmentRescheduleResource.Clear,b.resource);assertNull(b.directory!!.resource);assertEquals(choice.item,b.directory!!.service)
        b.openSelector(AppointmentBookingDirectoryKind.RESOURCE,b.control,service.control,resource.control);val reopened=b.selectorControl!!;b.useResource(chosen,rleaf,resourceSession);b.closeSelector(resourceSession);assertEquals(reopened,b.selectorControl);resource.select(resource.window!!.items.first {it.id==9003},resource.control);resource.choose(resource.control);b.useResource(resource.choice!!,resource.control,reopened);b.prepareReview(b.control);val input=b.review!!.input;assertEquals(raw,input.start.raw);assertEquals(s,b.source);b.submit(b.control);val retained=b.submission!!.attempt;val body=JSONObject(retained.body);assertEquals(8003,body.getInt("service"));assertEquals(9003,body.getInt("resource"));assertEquals(setOf("business","client","service","start_at","resource"),body.keys().asSequence().toSet());assertEquals(AppointmentBookingPhase.UNKNOWN,b.submission!!.phase)
        b.openSelector(AppointmentBookingDirectoryKind.SERVICE,b.control,service.control,resource.control);assertNull(b.selector);b.bind(null);b.bind(s.copy(epoch=2));assertTrue(b.blocked);assertFalse(b.canOpen);assertEquals(1,b.retainedAttemptCount)
    }
    @Test fun staleMatchingRereadLatePeerActorAndCandidateCompatibility()=runTest {
        val repo=APIReadRepository(transport());val refs=APIAppointmentReferenceRepository(transport());val s=source();val sr=services();val rr=resources();val b=AppointmentBookingModel(port(),repo,refs,sr,rr);b.bind(s);b.open(b.control);val service=b.serviceChoices!!;val resource=b.resourceChoices!!;b.openSelector(AppointmentBookingDirectoryKind.SERVICE,b.control,service.control,resource.control);val session=b.selectorControl!!;service.select(service.window!!.items[0],service.control);service.choose(service.control);val old=service.choice!!;val leaf=service.control;service.backToWindow(service.control);service.reload(service.control);b.useService(old,leaf,session);assertNull(b.service);service.select(service.window!!.items[0],service.control);service.choose(service.control);b.useService(service.choice!!,service.control,session);b.chooseClear(b.control);val proof=b.directory;b.back(b.control)
        val business=s.read.scope.business;val ref=refs.reference(AppointmentReferenceKind.SERVICE,101,8001);val intent=AppointmentSlotIntent.make(business,ref,null,"2026-11-02")!!;val rows=JSONObject(fixture("appointment-slot-read-fixtures")).getJSONArray("reads");val row=(0 until rows.length()).map {rows.getJSONObject(it)}.first {val q=it.getJSONObject("query");q.keys().asSequence().associateWith {k->q.getString(k)}==intent.query};val read=AppointmentSlotRead.decode(row.getString("response_json"),intent)!!;val context=AppointmentSlotReadContext.make(business,ref,null,read)!!;val time=AppointmentBookingCandidateTime.make(s,context.review(0)!!)!!;assertFalse(b.permitsCandidate(time));assertFalse(b.openCandidate(time,b.control));assertEquals(proof,b.directory)
        val held=Held();val late=AppointmentBookingModel(port(),repo,refs,held,rr);late.bind(s);late.open(late.control);val request=launch {late.openSelector(AppointmentBookingDirectoryKind.SERVICE,late.control,late.serviceChoices?.control,late.resourceChoices?.control)};runCurrent();val oldSession=late.selectorControl!!;late.closeSelector(oldSession);late.openSelector(AppointmentBookingDirectoryKind.RESOURCE,late.control,late.serviceChoices?.control,late.resourceChoices?.control);val current=late.selectorControl;held.windows[0].complete(sr.services(101));request.join();late.closeSelector(oldSession);assertEquals(current,late.selectorControl);assertNull(late.service);assertNull(late.serviceChoices!!.window);late.bind(null);late.bind(s);assertNull(late.selector)
        val actorPort=ActorPort(port().grants);val actor=AppointmentBookingModel(actorPort,repo,refs,sr,rr);actor.bind(s);actor.open(actor.control);actor.openSelector(AppointmentBookingDirectoryKind.SERVICE,actor.control,actor.serviceChoices?.control,actor.resourceChoices?.control);val actorSession=actor.selectorControl!!;val child=actor.serviceChoices!!;child.select(child.window!!.items[0],child.control);child.choose(child.control);actorPort.grants=emptyList();actor.useService(child.choice!!,child.control,actorSession);assertNull(actor.service);actor.closeSelector(actorSession);assertNull(child.window)
    }
}
